if not path.exists():path.write_text(json.dumps({'phase':'DISCOVERY_BEFORE_PRODUCT_EDITS','features':rows},indent=2),encoding='utf8')
matrix=json.loads(path.read_text(encoding='utf8'))
md='# Full feature parity matrix\n\nInitial source inspection is recorded separately from final validation. YES is a capability classification; runtime verification is recorded in test_coverage and regression/browser reports. Intentional unsupported capabilities are explicit.\n\n| Feature | Global | Library | Shared? | Parity? | Duplicate? | Action / canonical | Notes |\n|---|---|---|---|---|---|---|---|\n'
for r in matrix['features']:md+='| '+' | '.join([r['feature'],r['global_works'],r['library_works'],r['can_share_implementation'],r['feature_parity'],r['duplicated'],r['action']+' / '+r['canonical_implementation'],r['notes']]).replace('\n',' ')+' |\n'
(R/'full_feature_parity_matrix.md').write_text(md,encoding='utf8')
print('Parity matrix:',len(matrix['features']),'features;',matrix['phase'])
